  const filteredSelectorDevices=useMemo(()=>{const query=selectorDeviceQuery.trim().toLowerCase();return sortedSelectorDevices.filter(device=>(selectorRole==='All'||device.role===selectorRole)&&(!query||`${device.hostname} ${device.managementIp} ${device.model} ${roleOf(device)} ${mlagGroupByDeviceId.get(device.id)?.label||''}`.toLowerCase().includes(query)))},[mlagGroupByDeviceId,selectorDeviceQuery,selectorRole,sortedSelectorDevices]);
