    directAssignmentsOf(draft).forEach(assignment=>{const device=deviceById.get(assignment.deviceId);if(!device)errors.push(`Direct configuration references a device that is no longer registered in Inventory.`);if(appliedProfileByDeviceId.has(assignment.deviceId))errors.push(`${device?.hostname||assignment.deviceId} cannot retain direct port configuration while a VLAN Service Profile is applied.`);assignment.overrides?.forEach(override=>{const directValues={...directDefault,...override};const hasBusinessValue=override.portMode!==undefined||override.vlanId!==undefined||override.nativeVlanId!==undefined||override.allowedVlans!==undefined||override.gatewayAddress!==undefined||override.mtu!==undefined;if(!hasBusinessValue)return;if(directValues.portMode==='access'&&(!Number.isInteger(directValues.vlanId)||directValues.vlanId<1||directValues.vlanId>4094))errors.push(`${device?.hostname||assignment.deviceId} ${override.interfaceName} requires an Access VLAN from 1 to 4094.`);if(directValues.portMode==='trunk'&&(!Number.isInteger(directValues.nativeVlanId)||directValues.nativeVlanId<1||directValues.nativeVlanId>4094))errors.push(`${device?.hostname||assignment.deviceId} ${override.interfaceName} requires a Native VLAN ID from 1 to 4094.`);if(directValues.portMode==='trunk'&&directValues.allowedVlans&&!vlanListValid(directValues.allowedVlans))errors.push(`${device?.hostname||assignment.deviceId} ${override.interfaceName} requires valid Allowed VLANs.`);if(directValues.gatewayAddress&&!ipv4Cidr.test(directValues.gatewayAddress.trim()))errors.push(`${device?.hostname||assignment.deviceId} ${override.interfaceName} requires a valid Gateway in CIDR notation.`);if(!Number.isInteger(directValues.mtu)||directValues.mtu<1500||directValues.mtu>9216)errors.push(`${device?.hostname||assignment.deviceId} ${override.interfaceName} requires an MTU from 1500 to 9216.`)})});
